assert parse_query('q=hello+world') == {'q': ['hello world']}
assert parse_query('a=1&&b=2') == {'a': ['1'], 'b': ['2']}
assert parse_query('%C3%A9=1') == {'é': ['1']}
try:
    parse_query('a=%2')
    assert False
except ValueError:
    pass
