from urllib.parse import unquote_to_bytes

_HEXDIGITS = set("0123456789abcdefABCDEF")


def parse_query(qs: str) -> dict:
    def decode(component: str) -> str:
        i = 0
        while i < len(component):
            if component[i] == "%":
                if (
                    i + 2 >= len(component)
                    or component[i + 1] not in _HEXDIGITS
                    or component[i + 2] not in _HEXDIGITS
                ):
                    raise ValueError(f"malformed percent-escape in {component!r}")
                i += 3
            else:
                i += 1

        component = component.replace("+", " ")
        try:
            return unquote_to_bytes(component).decode("utf-8", errors="strict")
        except UnicodeDecodeError as exc:
            raise ValueError(f"invalid UTF-8 in {component!r}") from exc

    result = {}
    for pair in qs.split("&"):
        if not pair:
            continue
        key, separator, value = pair.partition("=")
        if not separator:
            value = ""
        decoded_key = decode(key)
        decoded_value = decode(value)
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
```

This preserves repeated-key order, ignores empty pairs, validates every percent escape, converts `+` to spaces, and decodes percent-encoded UTF-8 strictly.

