def parse_query(qs: str) -> dict:
    def decode_component(s: str) -> str:
        out = []
        byte_buf = bytearray()
        i = 0
        while i < len(s):
            c = s[i]
            if c == '%':
                if i + 2 >= len(s):
                    raise ValueError("malformed percent-escape")
                h1 = s[i + 1]
                h2 = s[i + 2]
                if h1 not in '0123456789abcdefABCDEF' or h2 not in '0123456789abcdefABCDEF':
                    raise ValueError("malformed percent-escape")
                byte_buf.append(int(h1 + h2, 16))
                i += 3
            else:
                if byte_buf:
                    out.append(byte_buf.decode('utf-8', errors='replace'))
                    byte_buf.clear()
                if c == '+':
                    out.append(' ')
                else:
                    out.append(c)
                i += 1
        if byte_buf:
            out.append(byte_buf.decode('utf-8', errors='replace'))
        return ''.join(out)

    result = {}
    for pair in qs.split('&'):
        if pair == '':
            continue
        key, sep, value = pair.partition('=')
        if not sep:
            value = ''
        decoded_key = decode_component(key)
        decoded_value = decode_component(value)
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
```

